package com.hfr.packet.builder;
import java.security.MessageDigest;import java.util.UUID;import com.hfr.builder.BuilderDepotService;import com.hfr.packet.PacketDispatcher;import com.hfr.schematic.*;import com.hfr.tileentity.machine.TileEntityMachineBuilder;import cpw.mods.fml.common.network.ByteBufUtils;import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.tileentity.TileEntity;
/** Authorized request for a native preview; response is always split into bounded chunks. */
public class BuilderSchematicDataRequestPacket implements IMessage{public int dimension,x,y,z;public String id="";public BuilderSchematicDataRequestPacket(){}public BuilderSchematicDataRequestPacket(int d,int x,int y,int z,String id){dimension=d;this.x=x;this.y=y;this.z=z;this.id=id;}public void fromBytes(ByteBuf b){dimension=b.readInt();x=b.readInt();y=b.readInt();z=b.readInt();id=ByteBufUtils.readUTF8String(b);}public void toBytes(ByteBuf b){b.writeInt(dimension);b.writeInt(x);b.writeInt(y);b.writeInt(z);ByteBufUtils.writeUTF8String(b,id);}public static class Handler implements IMessageHandler<BuilderSchematicDataRequestPacket,IMessage>{public IMessage onMessage(BuilderSchematicDataRequestPacket m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;if(p==null||p.dimension!=m.dimension||p.getDistanceSq(m.x+.5,m.y+.5,m.z+.5)>64)return null;TileEntity te=p.worldObj.getTileEntity(m.x,m.y,m.z);if(!(te instanceof TileEntityMachineBuilder)||!BuilderDepotService.mayView(p,(TileEntityMachineBuilder)te))return null;Schematic s=SchematicLibrary.get().resolve(m.id);if(s==null)return null;try{byte[] all=new SchematicPayload(s).encode(),digest=MessageDigest.getInstance("SHA-256").digest(all);int size=24576,total=(all.length+size-1)/size;String transfer=UUID.randomUUID().toString();for(int i=0;i<total;i++){int n=Math.min(size,all.length-i*size);byte[] part=new byte[n];System.arraycopy(all,i*size,part,0,n);PacketDispatcher.wrapper.sendTo(new BuilderSchematicDataChunkPacket(transfer,m.id,all.length,i,total,digest,part),p);}}catch(Exception ignored){}return null;}}}
